using MediatR;using Namaa.Application.Abstractions.Persistence;using Namaa.Application.PurchaseInvoices.Dtos;using Namaa.Domain.Common.Errors;using Namaa.Domain.Common.Results;namespace Namaa.Application.PurchaseInvoices.Commands.AddPurchaseInvoiceItem;public sealed class AddPurchaseInvoiceItemCommandHandler(IPurchaseInvoiceRepository repository,IApplicationDbContext db):IRequestHandler<AddPurchaseInvoiceItemCommand,Result<PurchaseInvoiceItemDto>>{public async Task<Result<PurchaseInvoiceItemDto>>Handle(AddPurchaseInvoiceItemCommand request,CancellationToken cancellationToken){var e=await repository.FindForUpdateAsync(request.PurchaseInvoiceId,cancellationToken);if(e is null)return Result.Failure<PurchaseInvoiceItemDto>(PurchaseInvoiceErrors.NotFound);if(e.Status.ToString()!="Draft")return Result.Failure<PurchaseInvoiceItemDto>(PurchaseInvoiceErrors.NotDraft);var i=e.AddItem(request.Description,request.Quantity,request.UnitPrice,request.DiscountAmount,request.TaxAmount,request.LineTotal);await db.SaveChangesAsync(cancellationToken);return Result.Success(PurchaseInvoiceItemDto.FromEntity(i));}}
